const heartbeats = $('Query Heartbeat Stats').all().map(i => i.json);
const decisions = $('Query Decision Overrides').all().map(i => i.json);

const report = ['# Weekly Agent Performance', ''];

// Heartbeat summary per agent
const agentStats = {};
for (const hb of heartbeats) {
  if (!agentStats[hb.name]) agentStats[hb.name] = {succeeded: 0, failed: 0, total: 0};
  agentStats[hb.name][hb.status] = (agentStats[hb.name][hb.status] || 0) + parseInt(hb.cnt);
  agentStats[hb.name].total += parseInt(hb.cnt);
}

report.push('## Heartbeat Success Rates');
for (const [name, stats] of Object.entries(agentStats)) {
  const rate = stats.total > 0 ? ((stats.succeeded || 0) / stats.total * 100).toFixed(0) : 'N/A';
  report.push(`- ${name}: ${rate}% (${stats.succeeded || 0}/${stats.total})`);
}

report.push('', '## Override Rates');
for (const d of decisions) {
  report.push(`- ${d.solver_used}: ${(d.override_rate * 100).toFixed(1)}% (${d.overrides}/${d.decisions})`);
}

return [{json: {report: report.join('\n')}}];
